CREATE OR REPLACE VIEW customer_invoice_summary AS SELECT c.customer_id,c.full_name,count(i.invoice_id) invoice_count,COALESCE(sum(i.total_amount),0) invoiced,COALESCE(sum(p.paid),0) paid,COALESCE(sum(i.total_amount),0)-COALESCE(sum(p.paid),0) outstanding FROM customers c LEFT JOIN invoices i ON i.customer_id=c.customer_id LEFT JOIN LATERAL (SELECT sum(amount) paid FROM payments WHERE invoice_id=i.invoice_id AND status IN ('SUCCESSFUL','PARTIALLY_REFUNDED')) p ON true GROUP BY c.customer_id,c.full_name;
CREATE OR REPLACE VIEW payment_summary AS SELECT p.payment_id,p.transaction_reference,p.payment_method,p.amount,p.status,p.payment_date,i.invoice_number,c.full_name customer FROM payments p JOIN invoices i ON i.invoice_id=p.invoice_id JOIN customers c ON c.customer_id=i.customer_id;
CREATE OR REPLACE VIEW monthly_revenue AS SELECT date_trunc('month',payment_date)::date AS month,sum(amount) revenue,count(*) payment_count FROM payments WHERE status IN ('SUCCESSFUL','PARTIALLY_REFUNDED') GROUP BY 1;
CREATE OR REPLACE VIEW outstanding_invoices AS SELECT i.invoice_id,i.invoice_number,c.full_name,i.due_date,i.total_amount,outstanding_balance(i.invoice_id) outstanding FROM invoices i JOIN customers c ON c.customer_id=i.customer_id WHERE i.status IN ('PENDING','PARTIALLY_PAID','OVERDUE');
CREATE OR REPLACE VIEW customer_payment_history AS SELECT c.customer_id,c.full_name,p.transaction_reference,p.amount,p.status,p.payment_date,i.invoice_number FROM customers c JOIN invoices i ON i.customer_id=c.customer_id JOIN payments p ON p.invoice_id=i.invoice_id;
